package ngap

// corpus_test.go — equivalence corpus round-trip (REL19-4.4). Every testdata/corpus/*.hex is one
// NGAP-PDU (amf-*, pcap-*) or one N2 SM transfer (smf-<TransferType>-*). Vectors are generated by
// the AMF/SMF corpus generators and tools/ngapcorpus; see testdata/corpus/README.md.

import (
	"bytes"
	"encoding/hex"
	"fmt"
	"os"
	"path/filepath"
	"reflect"
	"regexp"
	"sort"
	"strings"
	"testing"

	"github.com/free5gc/aper"

	"github.com/francurieses/claudia-5gc/shared/ngap/ngapType"
)

// minCorpusVectors is the acceptance floor of REL19-4.4.
const minCorpusVectors = 40

const corpusGlob = "testdata/corpus/*.hex"

// transferTypes maps the TransferTypeName in smf-<TransferTypeName>-<variant>.hex to the generated
// struct; transfers are encoded with the "valueExt" aper parameter (TS 38.413 §9.3.4).
var transferTypes = map[string]reflect.Type{
	"PDUSessionResourceSetupRequestTransfer":  reflect.TypeOf(ngapType.PDUSessionResourceSetupRequestTransfer{}),
	"PDUSessionResourceModifyRequestTransfer": reflect.TypeOf(ngapType.PDUSessionResourceModifyRequestTransfer{}),
	"PathSwitchRequestUnsuccessfulTransfer":   reflect.TypeOf(ngapType.PathSwitchRequestUnsuccessfulTransfer{}),
	"HandoverPreparationUnsuccessfulTransfer": reflect.TypeOf(ngapType.HandoverPreparationUnsuccessfulTransfer{}),
	"HandoverRequestAcknowledgeTransfer":      reflect.TypeOf(ngapType.HandoverRequestAcknowledgeTransfer{}),
	"HandoverCommandTransfer":                 reflect.TypeOf(ngapType.HandoverCommandTransfer{}),
	"PathSwitchRequestAcknowledgeTransfer":    reflect.TypeOf(ngapType.PathSwitchRequestAcknowledgeTransfer{}),
	"PathSwitchRequestTransfer":               reflect.TypeOf(ngapType.PathSwitchRequestTransfer{}),
	"PathSwitchRequestSetupFailedTransfer":    reflect.TypeOf(ngapType.PathSwitchRequestSetupFailedTransfer{}),
}

var smfNameRe = regexp.MustCompile(`^smf-([A-Za-z0-9]+)-`)

// corpusVector is one loaded vector.
type corpusVector struct {
	Name string // file name without .hex
	Data []byte
}

// transferTypeName returns the TransferTypeName of an smf-* vector, "" for NGAP-PDU vectors.
func transferTypeName(vec string) (string, error) {
	switch {
	case strings.HasPrefix(vec, "amf-"), strings.HasPrefix(vec, "pcap-"):
		return "", nil
	case strings.HasPrefix(vec, "smf-"):
		m := smfNameRe.FindStringSubmatch(vec)
		if m == nil {
			return "", fmt.Errorf("vector %q: cannot parse transfer type", vec)
		}
		return m[1], nil
	}
	return "", fmt.Errorf("vector %q: unknown prefix (want amf-, smf- or pcap-)", vec)
}

func loadCorpus() ([]corpusVector, error) {
	files, err := filepath.Glob(corpusGlob)
	if err != nil {
		return nil, err
	}
	sort.Strings(files)
	var out []corpusVector
	for _, f := range files {
		raw, err := os.ReadFile(f)
		if err != nil {
			return nil, err
		}
		b, err := hex.DecodeString(strings.TrimSpace(string(raw)))
		if err != nil {
			return nil, fmt.Errorf("%s: bad hex: %w", f, err)
		}
		out = append(out, corpusVector{Name: strings.TrimSuffix(filepath.Base(f), ".hex"), Data: b})
	}
	return out, nil
}

// reencodeTransfer decodes b into the new generated struct and re-encodes it.
func reencodeTransfer(typeName string, b []byte) ([]byte, error) {
	t, ok := transferTypes[typeName]
	if !ok {
		return nil, fmt.Errorf("unknown transfer type %q (add it to transferTypes)", typeName)
	}
	p := reflect.New(t)
	if err := aper.UnmarshalWithParams(b, p.Interface(), "valueExt"); err != nil {
		return nil, fmt.Errorf("decode %s: %w", typeName, err)
	}
	return aper.MarshalWithParams(p.Elem().Interface(), "valueExt")
}

// reencodeNew is the decode(new)→encode(new) result of one vector (PDU or transfer).
func reencodeNew(v corpusVector) ([]byte, error) {
	tn, err := transferTypeName(v.Name)
	if err != nil {
		return nil, err
	}
	if tn != "" {
		return reencodeTransfer(tn, v.Data)
	}
	pdu, err := Decoder(v.Data)
	if err != nil {
		return nil, err
	}
	return Encoder(*pdu)
}

func TestCorpusRoundTrip(t *testing.T) {
	vecs, err := loadCorpus()
	if err != nil {
		t.Fatal(err)
	}
	if len(vecs) < minCorpusVectors {
		t.Fatalf("corpus has %d vectors, want >= %d", len(vecs), minCorpusVectors)
	}
	bySrc := map[string]int{}
	for _, v := range vecs {
		bySrc[strings.SplitN(v.Name, "-", 2)[0]]++
		t.Run(v.Name, func(t *testing.T) {
			got, err := reencodeNew(v)
			if err != nil {
				t.Fatalf("round-trip: %v", err)
			}
			if !bytes.Equal(got, v.Data) {
				t.Fatalf("decode→encode differs\n got  %x\n want %x", got, v.Data)
			}
		})
	}
	t.Logf("corpus: %d vectors %v", len(vecs), bySrc)
}

// corpusKnownSUPIs are the test subscribers of the dev UDR seed / config; their IMSIs must never
// appear in a committed vector. MSINs are given as digit strings (IMSI minus MCC "001" + MNC "01").
var corpusKnownMSINs = []string{
	"0000000001", "0000000101", "0000000201", "0000000202",
	"0000000203", "0000000204", "0000000301", "0000000401",
}

// swappedBCD returns the TS 24.501 §9.11.3.4 SUCI MSIN encoding: digit pairs swapped per octet.
func swappedBCD(digits string) []byte {
	out := make([]byte, 0, len(digits)/2)
	for i := 0; i+1 < len(digits); i += 2 {
		out = append(out, (digits[i+1]-'0')<<4|(digits[i]-'0'))
	}
	return out
}

// TestCorpusNoSUPI asserts the sanitisation rule: no known test MSIN in BCD, and every null-scheme
// SUCI in a vector carries filler (all-zero) MSIN digits only.
func TestCorpusNoSUPI(t *testing.T) {
	vecs, err := loadCorpus()
	if err != nil {
		t.Fatal(err)
	}
	if len(vecs) < minCorpusVectors {
		t.Fatalf("corpus has %d vectors, want >= %d", len(vecs), minCorpusVectors)
	}
	for _, v := range vecs {
		for _, msin := range corpusKnownMSINs {
			if bytes.Contains(v.Data, swappedBCD(msin)) {
				t.Errorf("%s contains BCD of test MSIN %s", v.Name, msin)
			}
			if bytes.Contains(v.Data, []byte("imsi-")) {
				t.Errorf("%s contains a textual SUPI", v.Name)
			}
		}
		if strings.HasPrefix(v.Name, "smf-") {
			continue // N2 SM transfers carry no NAS, hence no SUCI
		}
		b := v.Data
		for i := 2; i+8 <= len(b); i++ {
			if b[i] != 0x01 || b[i+6] != 0x00 || b[i+7] != 0x00 {
				continue
			}
			l := int(b[i-2])<<8 | int(b[i-1])
			if l < 9 || l > 13 || i+l > len(b) {
				continue
			}
			if !bytes.Equal(b[i+8:i+l], make([]byte, l-8)) {
				t.Errorf("%s: null-scheme SUCI at offset %d has non-filler MSIN %x", v.Name, i, b[i+8:i+l])
			}
		}
	}
}
